void Solver::bump_var(int var, double coeff) {
    double bump_amount = var_inc * coeff;
    activity[var] += bump_amount;

    // Prevent overflow more efficiently by scaling less frequently
    if (activity[var] > 1e50) {
        double scale_factor = 1e-50;
        for (int i = 1; i <= vars; i++) activity[i] *= scale_factor;
        var_inc *= scale_factor;
    }

    // Update heap if variable is present
    if (vsids.inHeap(var)) vsids.update(var);
}
